def compute(vars):
    lease_obligations = vars["v1"]
    total_commitments = vars["v2"]

    if total_commitments == 0:
        return None

    ratio = lease_obligations / total_commitments
    value = ratio * 100

    return {
        "value": value,
        "trace": {
            "lease_obligations": lease_obligations,
            "total_commitments": total_commitments,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
